/bin/zsh -lc "cat > test/ledger.test.js <<'EOF'
const test = require('node:test');
const assert = require('node:assert/strict');
const { solve } = require('../src/index.js');

test('accepted IDs are duplicates regardless of payload or available funds', () => {
  const input = {
    balances: { a: 5, b: 0, c: 0 },
    events: [
      { id: 'x', from: 'a', to: 'b', amount: 5 },
      { id: 'x', from: 'a', to: 'b', amount: 5 },
      { id: 'x', from: 'b', to: 'c', amount: 2 },
    ],
  };
  const original = JSON.stringify(input);
  Object.freeze(input.balances);
  input.events.forEach(Object.freeze);
  Object.freeze(input.events);
  Object.freeze(input);
  assert.deepStrictEqual(solve(input), {
    balances: { a: 0, b: 5, c: 0 },
    versions: { a: 1, b: 1, c: 0 },
    receipts: [
      { id: 'x', status: 'applied' },
      { id: 'x', status: 'duplicate' },
      { id: 'x', status: 'duplicate' },
    ],
  });
  assert.equal(JSON.stringify(input), original);
  assert.equal(solve(input).receipts[0].status, 'applied');
});

test('rejected IDs can be retried after funding and with changed payloads', () => {
  assert.deepStrictEqual(solve({
    balances: { a: 0, b: 10 },
    events: [
      { id: 'retry', from: 'a', to: 'b', amount: 5 },
      { id: 'retry', from: 'a', to: 'b', amount: 5 },
      { id: 'fund', from: 'b', to: 'a', amount: 5 },
      { id: 'retry', from: 'a', to: 'b', amount: 5 },
      { id: 'changed', from: 'a', to: 'b', amount: 1 },
      { id: 'changed', from: 'b', to: 'a', amount: 3 },
    ],
  }), {
    balances: { a: 3, b: 7 },
    versions: { a: 3, b: 3 },
    receipts: [
      { id: 'retry', status: 'rejected' },
      { id: 'retry', status: 'rejected' },
      { id: 'fund', status: 'applied' },
      { id: 'retry', status: 'applied' },
      { id: 'changed', status: 'rejected' },
      { id: 'changed', status: 'applied' },
    ],
  });
});

test('empty collections are valid', () => {
  assert.deepStrictEqual(solve({ balances: {}, events: [] }), {
    balances: {}, versions: {}, receipts: [],
  });
});

test('prototype property names work as accounts and event IDs', () => {
  const balances = JSON.parse('{\"__proto__\":4,\"constructor\":0,\"toString\":0}');
  const result = solve({ balances, events: [
    { id: '__proto__', from: '__proto__', to: 'constructor', amount: 4 },
    { id: 'constructor', from: 'constructor', to: 'toString', amount: 2 },
    { id: '__proto__', from: 'toString', to: '__proto__', amount: 1 },
  ] });
  assert.deepStrictEqual(JSON.parse(JSON.stringify(result)), {
    balances: JSON.parse('{\"__proto__\":0,\"constructor\":2,\"toString\":2}'),
    versions: JSON.parse('{\"__proto__\":1,\"constructor\":2,\"toString\":1}'),
    receipts: [
      { id: '__proto__', status: 'applied' },
      { id: 'constructor', status: 'applied' },
      { id: '__proto__', status: 'duplicate' },
    ],
  });
});
EOF
node --test"

