const test = require('node:test');
const assert = require('node:assert/strict');
const { solve } = require('../src/index.js');

const move = (from, to, amount) => ({ from, to, amount });

test('batches use prior moves and increment each touched version once', () => {
  assert.deepStrictEqual(solve({
    balances: { a: 5, b: 0, c: 0 },
    events: [{ id: 'cycle', moves: [move('a', 'b', 5), move('b', 'c', 5), move('c', 'a', 5)] }],
  }), {
    balances: { a: 5, b: 0, c: 0 },
    versions: { a: 1, b: 1, c: 1 },
    receipts: [{ id: 'cycle', status: 'applied' }],
  });
});

test('failed batches roll back all state and leave their IDs available', () => {
  assert.deepStrictEqual(solve({
    balances: { a: 5, b: 0, c: 0 },
    events: [
      { id: 'retry', moves: [move('a', 'b', 5), move('b', 'c', 6)] },
      { id: 'retry', expected: { a: 0, b: 0, c: 0 }, moves: [move('a', 'b', 5)] },
      { id: 'ordered', moves: [move('a', 'c', 1), move('b', 'a', 1)] },
    ],
  }), {
    balances: { a: 0, b: 5, c: 0 },
    versions: { a: 1, b: 1, c: 0 },
    receipts: [
      { id: 'retry', status: 'rejected' },
      { id: 'retry', status: 'applied' },
      { id: 'ordered', status: 'rejected' },
    ],
  });
});

test('expected versions apply to transfers, batches, and untouched accounts', () => {
  assert.deepStrictEqual(solve({
    balances: { a: 5, b: 0, c: 0 },
    events: [
      { id: 'x', ...move('a', 'b', 2), expected: { c: 1 } },
      { id: 'x', ...move('a', 'b', 2), expected: { a: 0, c: 0 } },
      { id: 'x', moves: [], expected: { a: 0 } },
      { id: 'y', moves: [move('b', 'a', 1)], expected: { b: 0 } },
      { id: 'y', moves: [move('b', 'a', 1)], expected: { b: 1 } },
    ],
  }), {
    balances: { a: 4, b: 1, c: 0 },
    versions: { a: 2, b: 2, c: 0 },
    receipts: [
      { id: 'x', status: 'rejected' },
      { id: 'x', status: 'applied' },
      { id: 'x', status: 'duplicate' },
      { id: 'y', status: 'rejected' },
      { id: 'y', status: 'applied' },
    ],
  });
});

test('empty batches check expectations, reserve accepted IDs, and change no versions', () => {
  assert.deepStrictEqual(solve({
    balances: { a: 0 },
    events: [
      { id: 'empty', moves: [], expected: { a: 1 } },
      { id: 'empty', moves: [], expected: { a: 0 } },
      { id: 'empty', moves: [], expected: { a: 1 } },
    ],
  }), {
    balances: { a: 0 }, versions: { a: 0 },
    receipts: [
      { id: 'empty', status: 'rejected' },
      { id: 'empty', status: 'applied' },
      { id: 'empty', status: 'duplicate' },
    ],
  });
  assert.deepStrictEqual(solve({ balances: {}, events: [{ id: 'x', moves: [] }] }), {
    balances: {}, versions: {}, receipts: [{ id: 'x', status: 'applied' }],
  });
});

test('batch drafts support prototype names and do not mutate nested input', () => {
  const input = {
    balances: JSON.parse('{\"__proto__\":4,\"constructor\":0}'),
    events: [{
      id: '__proto__',
      moves: [move('__proto__', 'constructor', 4), move('constructor', '__proto__', 1)],
      expected: JSON.parse('{\"__proto__\":0,\"constructor\":0}'),
    }],
  };
  const original = JSON.stringify(input);
  function freeze(value) {
    if (value && typeof value === 'object') {
      Object.values(value).forEach(freeze);
      Object.freeze(value);
    }
  }
  freeze(input);
  assert.deepStrictEqual(solve(input), {
    balances: JSON.parse('{\"__proto__\":1,\"constructor\":3}'),
    versions: JSON.parse('{\"__proto__\":1,\"constructor\":1}'),
    receipts: [{ id: '__proto__', status: 'applied' }],
  });
  assert.equal(JSON.stringify(input), original);
});
EOF
node --test"

