const test = require('node:test');
const assert = require('node:assert/strict');
const { solve } = require('../src/index.js');
const node = (id, deps = [], revision = 0) => ({ id, deps, revision });
const request = (targets, changes = []) => ({ targets, changes });

test('selects the smallest currently ready ID, with distinct dependencies', () => {
  assert.deepEqual(solve({
    nodes: [node('a', ['z', 'z']), node('b'), node('c', ['b']), node('z')],
    requests: [request(['a', 'c', 'a']), request(['a', 'c'])]
  }), [
    { built: ['b', 'c', 'z', 'a'], cached: [] },
    { built: [], cached: ['b', 'c', 'z', 'a'] }
  ]);
});

test('dependency builds invalidate consumers even across separate requests', () => {
  assert.deepEqual(solve({
    nodes: [node('leaf'), node('middle', ['leaf']), node('root', ['middle', 'leaf']), node('other')],
    requests: [
      request(['root']),
      request(['leaf'], [{ id: 'leaf', revision: 1 }]),
      request(['leaf'], [{ id: 'leaf', revision: 0 }]),
      request(['root']),
      request(['root'], [{ id: 'other', revision: 5 }])
    ]
  }), [
    { built: ['leaf', 'middle', 'root'], cached: [] },
    { built: ['leaf'], cached: [] },
    { built: ['leaf'], cached: [] },
    { built: ['middle', 'root'], cached: ['leaf'] },
    { built: [], cached: ['leaf', 'middle', 'root'] }
  ]);
});

test('applies changes in order, including requests without targets', () => {
  const input = {
    nodes: [node('__proto__'), node('constructor', ['__proto__'])],
    requests: [
      request(['constructor']),
      request([], [{ id: '__proto__', revision: 2 }]),
      request(['constructor']),
      request(['constructor'], [{ id: '__proto__', revision: 3 }, { id: '__proto__', revision: 2 }]),
      request(['constructor'], [{ id: 'constructor', revision: -1 }]),
      request(['constructor'], [{ id: 'constructor', revision: 0 }])
    ]
  };
  const original = JSON.stringify(input);
  const expected = [
    { built: ['__proto__', 'constructor'], cached: [] },
    { built: [], cached: [] },
    { built: ['__proto__', 'constructor'], cached: [] },
    { built: [], cached: ['__proto__', 'constructor'] },
    { built: ['constructor'], cached: ['__proto__'] },
    { built: ['constructor'], cached: ['__proto__'] }
  ];
  assert.deepEqual(solve(input), expected);
  assert.deepEqual(solve(input), expected);
  assert.equal(JSON.stringify(input), original);
});

test('handles long chains with many shared dependency paths', () => {
  const nodes = [];
  for (let i = 0; i < 12000; i++) {
    nodes.push(node(String(i).padStart(5, '0'),
      [i - 1, i - 2].filter(j => j >= 0).map(j => String(j).padStart(5, '0'))));
  }
  const ids = nodes.map(n => n.id);
  assert.deepEqual(solve({ nodes, requests: [request([ids.at(-1)]), request([ids.at(-1)])] }), [
    { built: ids, cached: [] }, { built: [], cached: ids }
  ]);
});

test('empty graph and empty requests', () => {
  assert.deepEqual(solve({ nodes: [], requests: [request([])] }), [{ built: [], cached: [] }]);
  assert.deepEqual(solve({ nodes: [], requests: [] }), []);
});
