  assert.deepEqual(solve({
    roles: [role('base', [], [rule('allow', { until: 5 })]),
      role('leaf', ['base'], [rule('deny', { until: 0 })])],
    users: [{ id: 'u', roles: ['leaf'] }],
    queries: [-1, 0, 4, 5, 6, -10].map(time => query('u', time))
